draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 120, H/2 + 20); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 80, H/2 + 20); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 90, H/2 + 80); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 110, H/2 + 80); // leg
  ctx.stroke();

  // animate stick figure eating apple
  ctx.save();
  ctx.translate(W/2 - 100, H/2 - 30);
  ctx.rotate(Math.sin(t) * Math.PI / 4);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(0, -20); // arm eating
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
